struct Buffer {
  int* data_; std::size_t size_;
  explicit Buffer(std::size_t n)
    : data_(new int[n]{}), size_(n) {}
  ~Buffer() { delete[] data_; }
};
void print(Buffer b) {
  std::cout << "size " << b.size_ << '\n';
}
int main() {
  Buffer a(4); print(a);
}

// Rule of 3: deep copy
Buffer(const Buffer& o)
    : data_(new int[o.size_]),
      size_(o.size_) {
    std::copy_n(o.data_, size_, data_);
}
Buffer& operator=(const Buffer&) = delete;

// and no copy needed here at all
void print(const Buffer& b);

struct Msg {
  Msg(int) {}
  Msg(const Msg&) { std::cout << "copy "; }
  Msg(Msg&&) { std::cout << "move "; }
};
int main() {
  std::vector<Msg> v;
  for (int i = 0; i < 3; ++i) {
    v.emplace_back(i);
    std::cout << "| ";
  }
}

Msg(Msg&&) noexcept { std::cout << "move "; }
// now prints: | move | move move |

static_assert(
  std::is_nothrow_move_constructible_v<Msg>);

struct Buf {          // Rule of 0
  std::vector<int> data;
  explicit Buf(std::size_t n) : data(n) {}
};
int main() {
  Buf a(3);
  Buf b = a;               // copy
  b.data[0] = 7;
  Buf c = std::move(a);    // move
  std::cout << c.data[0] << ' ';
  std::cout << noexcept(Buf(std::move(b)));
}

struct Item {
  Item() = default;
  Item(const Item&) { puts("copy"); }
  Item(Item&&) noexcept { puts("move"); }
};
struct Logged { Item o; ~Logged() {} };
int main() {
  std::vector<Logged> v(2);
  v.reserve(3);
}

struct Logged {
  Item o;
  ~Logged() {}
  Logged() = default;
  Logged(Logged&&) = default;
  Logged(const Logged&) = default;
};
// reserve(3) now prints: move move
